 function updateUiPreferences(next:UiPreferences){try{saveUiPreferences(next);setUiPreferences(next);setError('')}catch(e){setError(e instanceof Error?e.message:'Could not save display preferences.')}}
 function clearUserData(){setSavedRecommendations([]);setGoals([]);setCareerGoals([]);setGoalRoadmaps({});setRoadmapItems([]);setActiveGoalId(null);setResult(null);setDraftRoadmap(null);setDraftNotice('');setWorkspaceNotice('');setWorkspaceError('')}
 function clearLocalSession(message:string){localStorage.removeItem('ssp_user');setUser(null);clearUserData();setWorkspaceError(message);setPage('Home');setAuthMode('login');setError(message);setShowAuth(true)}
 async function authenticatedRequest(path:string,init:RequestInit={}){if(!user?.token)throw new Error('Please sign in to access your saved workspace.');const response=await fetch(`${API}${path}`,{...init,headers:{'Content-Type':'application/json',...init.headers,Authorization:`Bearer ${user.token}`}});const data=await response.json().catch(()=>null);if(response.status===401){clearLocalSession('Your session has expired or is no longer valid. Please sign in again.');throw new Error(data?.detail||'Your session has expired. Please sign in again.')}if(!response.ok)throw new Error(data?.detail||'The request could not be completed. Please try again.');return data}
 async function loadWorkspace(){if(!user?.token)return;setWorkspaceLoading(true);setWorkspaceError('');try{const [recommendationData,legacyGoalData,careerGoalData]=await Promise.all([authenticatedRequest('/api/recommendations'),authenticatedRequest('/api/goals'),authenticatedRequest('/api/career-goals')]);const roadmaps=await Promise.all((careerGoalData.goals as CareerGoal[]).map(async goal=>{const data=await authenticatedRequest(`/api/roadmap?goal_id=${goal.id}`);return [goal.id,data.items as RoadmapItem[]] as const}));const roadmapMap=Object.fromEntries(roadmaps) as Record<number,RoadmapItem[]>;setSavedRecommendations(recommendationData.recommendations);setGoals(legacyGoalData.goals);setCareerGoals(careerGoalData.goals);setGoalRoadmaps(roadmapMap);const nextId=(careerGoalData.goals as CareerGoal[]).some(goal=>goal.id===activeGoalId)?activeGoalId:(careerGoalData.goals[0]?.id??null);setActiveGoalId(nextId);setRoadmapItems(nextId?roadmapMap[nextId]||[]:[])}catch(e){setWorkspaceError(e instanceof Error?e.message:'Could not load your personal workspace.')}finally{setWorkspaceLoading(false)}}
 async function refreshWorkspace(){await loadWorkspace()}
 async function addGoal(){const value=goalInput.trim();if(!value){setWorkspaceError('Enter a learning goal before adding it.');return}if(value.length>300){setWorkspaceError('Goals must be 300 characters or fewer.');return}if(goals.length>=100){setWorkspaceError('You can save up to 100 goals.');return}setWorkspaceBusy(true);setWorkspaceError('');setWorkspaceNotice('');try{await authenticatedRequest('/api/goals',{method:'POST',body:JSON.stringify({goals:[...goals,value]})});setGoalInput('');await refreshWorkspace();setWorkspaceNotice('Goal saved.')}catch(e){setWorkspaceError(e instanceof Error?e.message:'Could not save the goal.')}finally{setWorkspaceBusy(false)}}
 async function removeGoal(index:number){const next=goals.filter((_,i)=>i!==index);setWorkspaceBusy(true);setWorkspaceError('');setWorkspaceNotice('');try{await authenticatedRequest('/api/goals',{method:'POST',body:JSON.stringify({goals:next})});await refreshWorkspace();setWorkspaceNotice('Goal removed.')}catch(e){setWorkspaceError(e instanceof Error?e.message:'Could not update your goals.')}finally{setWorkspaceBusy(false)}}
 async function saveRoadmapDraft(){
  if(!draftRoadmap?.length){setError('There are no roadmap steps to save. Add a step or generate a new draft.');return}
  if(!user){setAuthMode('login');setError('Sign in to save this roadmap to your account.');setShowAuth(true);return}
  if(!careerGoalTitle.trim()||!careerGoalCareer.trim()){setError('Enter a goal title and target career before saving.');return}
  if(draftRoadmap.some(step=>!step.title.trim()||!step.phase.trim())){setError('Every roadmap step needs a title and phase.');return}
  if(draftRoadmap.some(step=>step.resourceUrl&&!isHttpUrl(step.resourceUrl.trim()))){setError('Resource links must begin with http:// or https://.');return}
  const roadmapSteps=draftRoadmap.map(step=>({
   title:step.title.trim(),
   description:encodeRoadmapDescription({notes:step.description.trim(),category:step.category,resourceUrl:step.resourceUrl.trim(),stepType:step.stepType}),
   phase:step.phase.trim(),
   priority:step.priority,
   status:step.status,
  }));
  if(roadmapSteps.some(step=>step.description.length>2000)){setError('Shorten a roadmap description or resource link to fit the saved step limit.');return}
  setWorkspaceBusy(true);setError('');setNotice('');
  try{
   await authenticatedRequest('/api/career-goals',{method:'POST',body:JSON.stringify({title:careerGoalTitle.trim(),target_career:careerGoalCareer.trim(),description:careerGoalDescription.trim(),target_date:careerGoalDate||null,roadmap_steps:roadmapSteps})});
   setDraftRoadmap(null);setDraftNotice('');setPage('My Space');setWorkspaceNotice('Career goal and roadmap saved.');
  }catch(e){setError(e instanceof Error?e.message:'Could not save the roadmap.')}
  finally{setWorkspaceBusy(false)}
 }
 async function updateCareerGoal(goalId:number,changes:Partial<Pick<CareerGoal,'title'|'target_career'|'description'|'target_date'|'status'>>){setWorkspaceBusy(true);setWorkspaceError('');setWorkspaceNotice('');try{await authenticatedRequest(`/api/career-goals/${goalId}`,{method:'PATCH',body:JSON.stringify(changes)});await refreshWorkspace();setWorkspaceNotice('Career goal updated.')}catch(e){setWorkspaceError(e instanceof Error?e.message:'Could not update the career goal.')}finally{setWorkspaceBusy(false)}}
