 async function addRoadmapItem(e:React.FormEvent){e.preventDefault();const title=roadmapTitle.trim();const description=roadmapDescription.trim();if(!title){setWorkspaceError('Enter a title for this roadmap item.');return}if(!activeGoalId){setWorkspaceError('Select or create a career goal before adding roadmap steps.');return}setWorkspaceBusy(true);setWorkspaceError('');setWorkspaceNotice('');try{await authenticatedRequest('/api/roadmap',{method:'POST',body:JSON.stringify({title,description,goal_id:activeGoalId,phase:'Skill Development',priority:'medium'})});setRoadmapTitle('');setRoadmapDescription('');await refreshWorkspace();setWorkspaceNotice('Roadmap item added.')}catch(e){setWorkspaceError(e instanceof Error?e.message:'Could not add the roadmap item.')}finally{setWorkspaceBusy(false)}}
