 async function deleteRoadmapItem(item:RoadmapItem){setWorkspaceBusy(true);setWorkspaceError('');setWorkspaceNotice('');try{await authenticatedRequest(`/api/roadmap/${item.id}`,{method:'DELETE'});await refreshWorkspace();setWorkspaceNotice('Roadmap item deleted.')}catch(e){setWorkspaceError(e instanceof Error?e.message:'Could not delete the roadmap item.')}finally{setWorkspaceBusy(false)}}
 async function deleteSavedRecommendation(item:SavedRecommendation){setWorkspaceBusy(true);setWorkspaceError('');setWorkspaceNotice('');try{await authenticatedRequest(`/api/recommendations/${item.id}`,{method:'DELETE'});await refreshWorkspace();setWorkspaceNotice('Saved recommendation deleted.')}catch(e){setWorkspaceError(e instanceof Error?e.message:'Could not delete the saved recommendation.')}finally{setWorkspaceBusy(false)}}
 async function saveRecommendation(){if(!result)return;if(!selected.length){setError('Select at least one current skill before saving a recommendation.');return}setWorkspaceBusy(true);setError('');setNotice('');try{await authenticatedRequest('/api/recommendations',{method:'POST',body:JSON.stringify({career,selected_skills:selected,results:result})});await refreshWorkspace();setNotice('Recommendation saved to My Space.')}catch(e){setError(e instanceof Error?e.message:'Could not save the recommendation.')}finally{setWorkspaceBusy(false)}}
 function generateRoadmapDraft(){
  setDraftNotice('');
  if(!result){setError('Generate a recommendation before creating a roadmap draft.');return}
  const modelSkills=resultLabels(result.skill_gap?.length?result.skill_gap:result.recommended_skills);
  const isSelected=(skill:string)=>selected.some(current=>current.toLowerCase()===skill.toLowerCase());
  const missing=Array.from(new Set([
   ...modelSkills.filter(skill=>!isSelected(skill)),
   ...(skillsByCareer[career]||[]).filter(skill=>!isSelected(skill)),
  ])).slice(0,4);
  const matchingRoles=resultLabels(result.matching_roles);
  const certifications=(result.certifications||[])
   .map(resolveCertification)
   .filter((certification):certification is {name:string;url?:string}=>Boolean(certification));
  if(!missing.length&&!matchingRoles.length&&!certifications.length){
   setDraftRoadmap(null);
   setDraftNotice(`The recommendation and available skill checklist do not contain enough career-specific information for a meaningful ${career} plan. You can add roadmap steps manually in My Space.`);
   return;
  }
  const steps:CareerRoadmapDraftStep[]=[];
  const addStep=(step:CareerRoadmapDraftStep)=>steps.push(step);
  const firstSkill=missing[0]||selected[0]||'career fundamentals';
  addStep({
   phase:'Fundamentals',
   title:`Assess your skills for ${career}`,
   description:`Compare your current skills (${selected.join(', ')}) with ${modelSkills.length?'the model-returned skill recommendations and ':''}the available ${career} skill checklist. The checklist is application reference data, not an additional model result.`,
   priority:'high',stepType:'Practice',category:career,resourceUrl:'',status:'not_started',
  });
  if(missing.length){
   for(const [index,skill] of missing.slice(0,3).entries()){
    addStep({phase:index===0?'Fundamentals':'Skill Development',title:`Learn ${skill}`,description:`Build working knowledge of ${skill}, then practice the basics before moving to larger tasks. This skill is ${modelSkills.some(item=>item.toLowerCase()===skill.toLowerCase())?'included in the model recommendation':'listed in the available career skill checklist'}.`,priority:index===0?'high':'medium',stepType:'Learn a Skill',category:skill,resourceUrl:'',status:'not_started'});
   }
  }else{
   addStep({phase:'Skill Development',title:`Strengthen ${firstSkill}`,description:`Review and practice one of your selected skills in the context of ${career}; the recommendation did not identify a missing skill.`,priority:'medium',stepType:'Practice',category:firstSkill,resourceUrl:'',status:'not_started'});
  }
  if(certifications.length){
   const certification=certifications[0];
   addStep({phase:'Skill Development',title:`Review ${certification.name}`,description:'This certification name was returned by the recommendation model. Check its current requirements and fit before deciding whether to pursue it.',priority:'medium',stepType:'Earn a Certification',category:'',resourceUrl:certification.url||'',status:'not_started'});
  }else{
   addStep({phase:'Skill Development',title:`Choose learning materials for ${firstSkill}`,description:'Compare course outlines from reputable providers against the skills in this roadmap. No specific course was returned by the recommendation model.',priority:'medium',stepType:'Complete a Course',category:firstSkill,resourceUrl:'',status:'not_started'});
  }
  addStep({phase:'Practical Projects',title:`Practice ${firstSkill} with hands-on exercises`,description:`Complete small exercises using ${firstSkill}, and note what you can now do independently for ${career}.`,priority:'medium',stepType:'Practice',category:firstSkill,resourceUrl:'',status:'not_started'});
  addStep({phase:'Practical Projects',title:`Build a practical ${career} project`,description:`Create a small project that demonstrates ${missing.slice(0,2).join(' and ')||selected.slice(0,2).join(' and ')}. Choose the project scope yourself; no project output was generated by the recommendation model.`,priority:'high',stepType:'Build a Project',category:career,resourceUrl:'',status:'not_started'});
  addStep({phase:'Portfolio and Career Preparation',title:`Document your work in a portfolio`,description:`Present the project, your role, tools used, and what you learned in a clear portfolio entry relevant to ${career}.`,priority:'medium',stepType:'Prepare a Portfolio',category:career,resourceUrl:'',status:'not_started'});
  addStep({phase:'Portfolio and Career Preparation',title:`Prepare for ${career} opportunities`,description:`Review current role descriptions${matchingRoles.length?` such as ${matchingRoles[0]}`:''}, identify recurring requirements, and prepare examples from your project for applications or interviews.`,priority:'low',stepType:'Gain Experience',category:career,resourceUrl:'',status:'not_started'});
  setCareerGoalTitle(career);
  setCareerGoalCareer(career);
  setCareerGoalDescription('');
  setCareerGoalDate('');
  setDraftRoadmap(steps);
  setDraftEditing(false);
  setDraftNotice('Draft created. Skill-gap steps use returned model results and the available career skill checklist; course, practice, project, portfolio, and preparation steps are a transparent rule-based plan. Review it before saving.');
 }
 function moveDraftStep(index:number,direction:-1|1){if(!draftRoadmap)return;const target=index+direction;if(target<0||target>=draftRoadmap.length)return;const next=[...draftRoadmap];[next[index],next[target]]=[next[target],next[index]];setDraftRoadmap(next)}
 function editDraftStep(index:number,changes:Partial<CareerRoadmapDraftStep>){setDraftRoadmap(current=>current?.map((step,stepIndex)=>stepIndex===index?{...step,...changes}:step)??null)}
 function addDraftStep(){setDraftRoadmap(current=>[...(current||[]),{phase:'Skill Development',title:'',description:'',priority:'medium',stepType:'Other',category:'',resourceUrl:'',status:'not_started'}])}
 async function signOut(switchAccount=false){
  let logoutError='';
  try{await authenticatedRequest('/api/auth/logout',{method:'POST'})}
  catch(e){logoutError=e instanceof Error?e.message:'The server could not confirm sign-out.'}
  localStorage.removeItem('ssp_user');
  setUser(null);
  clearUserData();
  setCareerGoalTitle('');
  setCareerGoalCareer('Frontend Developer');
  setCareerGoalDescription('');
  setCareerGoalDate('');
  setPage('Home');
  setAuthMode('login');
  setPassword('');
  setEmail('');
  setShowAuth(switchAccount);
  setNotice(logoutError
   ?`Signed out on this device, but server token revocation could not be confirmed: ${logoutError}`
   :switchAccount?'Sign in with another account.':'You have signed out.');
 }
 useEffect(()=>{if(!result||page!=='Explore')return;const timer=window.setTimeout(()=>resultsRef.current?.scrollIntoView({behavior:prefersReducedMotion?'auto':'smooth',block:'start'}),100);return()=>window.clearTimeout(timer)},[result,page,prefersReducedMotion]);
 useEffect(()=>{if(!showRecommendationModal)return;const closeOnEscape=(event:KeyboardEvent)=>{if(event.key==='Escape')setShowRecommendationModal(false)};window.addEventListener('keydown',closeOnEscape);return()=>window.removeEventListener('keydown',closeOnEscape)},[showRecommendationModal]);
 const careerSkills=skillsByCareer[career]||[];
 const recommendedCerts=useMemo(()=>{const key=career.toLowerCase();let terms=key.includes('data')?['data','analytics','computer science']:key.includes('web')||key.includes('front')?['web','front-end','computer science']:key.includes('cloud')||key.includes('devops')?['cloud','azure','computer science']:key.includes('cyber')?['cyber','computer science']:key.includes('machine learning')||key.includes('scientist')?['data','computer science']:['computer science'];return certs.filter(c=>terms.some(t=>(c.name+' '+c.skills+' '+c.provider).toLowerCase().includes(t))).slice(0,4)},[career]);
 async function generate(){if(loading)return;if(!career){setError('Choose a career interest before analyzing your skills.');return}if(!selected.length){setError('Select at least one skill you already have before analyzing your career fit.');return}setLoading(true);setShowRecommendationModal(false);setError('');setNotice('');try{const r=await fetch(`${API}/api/recommend`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({career,current_skills:selected})});const data=await r.json().catch(()=>null);if(!r.ok)throw new Error(data?.detail||'Recommendation service could not respond. Please make sure the SmartSkillPath backend is running.');if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('The recommendation service returned an unexpected response. Please try again.');setResult(data);setShowRecommendationModal(true);setNotice('Your guest recommendation is ready. It has not been saved.')}catch(e){setError(e instanceof Error?e.message:'Could not generate recommendations.')}finally{setLoading(false)}}
 async function authSubmit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setError('');try{const r=await fetch(`${API}/api/auth/${authMode}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});const d=await r.json().catch(()=>null);if(!r.ok)throw new Error(d?.detail||'Unable to continue');if(typeof d?.email!=='string'||typeof d?.token!=='string')throw new Error('The authentication service returned an invalid session.');const next:UserSession={email:d.email,token:d.token};localStorage.setItem('ssp_user',JSON.stringify(next));setUser(next);setShowAuth(false);setPassword('');setPage(draftRoadmap?'Explore':'My Space');setNotice('Welcome to your personal Skill Space.')}catch(e){setError(e instanceof Error?e.message:'Unable to sign in.')}}
 function toggleSkill(skill:string){setSelected(p=>p.includes(skill)?p.filter(s=>s!==skill):[...p,skill]);setResult(null)}
 function navigate(next:AppPage){setPage(next==='About'?'AboutExpanded':next);if(next!=='My Space')setWorkspaceNotice('');setError('');window.scrollTo({top:0,behavior:'smooth'});}
